using System.Data;
using System.Security.Claims;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using SoodalLife.Api.Domain.Entities;
using SoodalLife.Api.Features.Authentication;
using SoodalLife.Api.Features.Matching;
using SoodalLife.Api.Infrastructure.Persistence;
using SoodalLife.Api.Infrastructure.Security;

namespace SoodalLife.Api.Features.Subscriptions;

public sealed class CareSubscriptionService(SoodalLifeDbContext db,ProviderTradingEligibilityService eligibility,ISubscriptionVisitVerificationAdapter visitVerification,IPrivacyContract privacyContract)
{
    private const int RollingWindowDays=90;
    private static readonly string[] Frequencies=["WEEKLY","BIWEEKLY","MONTHLY","QUARTERLY","HALF_YEARLY"];

    public async Task<IReadOnlyList<SubscriptionServiceItem>> GetEligibleServices(CancellationToken token)
    {
        var today=DateOnly.FromDateTime(DateTime.UtcNow);
        return await (from service in db.ServiceCategories.AsNoTracking()
                      join middle in db.ServiceCategories.AsNoTracking() on service.ParentId equals middle.Id
                      join major in db.ServiceCategories.AsNoTracking() on middle.ParentId equals major.Id
                      where service.LevelCode=="SERVICE"&&service.StatusCode=="ACTIVE"&&
                            db.CategoryOperationPolicies.Any(p=>p.CategoryId==service.Id&&p.IsActive&&p.EffectiveFrom<=today&&(p.EffectiveTo==null||p.EffectiveTo>today)&&p.SubscriptionOptionText=="허용")
                      orderby major.SortOrder,middle.SortOrder,service.SortOrder
                      select new SubscriptionServiceItem(service.PublicId,major.Name,middle.Name,service.Name,$"{major.Name} > {middle.Name} > {service.Name}")).ToListAsync(token);
    }

    public async Task<CareProductResponse> CreateProduct(CreateCareProductRequest input,Guid actorPublicId,CancellationToken token)
    {
        if(input.StandardMonthlyAmount<0||input.StandardVisitAmount<0)throw Bad("SUBSCRIPTION_AMOUNT_INVALID","금액은 0원 이상이어야 합니다."); if(input.EffectiveTo<=input.EffectiveFrom)throw Bad("PRODUCT_PERIOD_INVALID","상품 적용기간을 확인해 주세요.");
        var actor=await AdminId(actorPublicId,token);var category=await EligibleCategory(input.ServiceCategoryId,token);var now=DateTime.UtcNow;
        var item=new CareProduct{ServiceCategoryId=category.Id,ProductName=input.ProductName.Trim(),Description=Clean(input.Description),ServiceScopeText=input.ServiceScopeText.Trim(),VisitsPerPeriod=input.VisitsPerPeriod,ExpectedDurationMinutes=input.ExpectedDurationMinutes,BillingPeriodCode=Code(input.BillingPeriodCode),StandardMonthlyAmount=input.StandardMonthlyAmount,StandardVisitAmount=input.StandardVisitAmount,IsActive=input.IsActive,EffectiveFrom=input.EffectiveFrom,EffectiveTo=input.EffectiveTo,CreatedAt=now,CreatedByUserId=actor,UpdatedAt=now,UpdatedByUserId=actor};
        db.CareProducts.Add(item);await db.SaveChangesAsync(token);return MapProduct(item,category.PublicId,category.Name);
    }

    public async Task<IReadOnlyList<CareProductResponse>> GetProducts(CancellationToken token)
    {
        var rows=await(from item in db.CareProducts.AsNoTracking()join category in db.ServiceCategories.AsNoTracking()on item.ServiceCategoryId equals category.Id orderby item.IsActive descending,item.ProductName select new{item,category.PublicId,category.Name}).ToListAsync(token);
        return rows.Select(x=>MapProduct(x.item,x.PublicId,x.Name)).ToArray();
    }

    public async Task<CareProductResponse> UpdateProduct(Guid id,CreateCareProductRequest input,Guid actorPublicId,CancellationToken token)
    {
        if(input.StandardMonthlyAmount<0||input.StandardVisitAmount<0)throw Bad("SUBSCRIPTION_AMOUNT_INVALID","금액은 0원 이상이어야 합니다.");if(input.EffectiveTo<=input.EffectiveFrom)throw Bad("PRODUCT_PERIOD_INVALID","상품 적용기간을 확인해 주세요.");var actor=await AdminId(actorPublicId,token);var item=await db.CareProducts.SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw NotFound("CARE_PRODUCT_NOT_FOUND","구독상품을 찾을 수 없습니다.");var category=await EligibleCategory(input.ServiceCategoryId,token);item.ServiceCategoryId=category.Id;item.ProductName=input.ProductName.Trim();item.Description=Clean(input.Description);item.ServiceScopeText=input.ServiceScopeText.Trim();item.VisitsPerPeriod=input.VisitsPerPeriod;item.ExpectedDurationMinutes=input.ExpectedDurationMinutes;item.BillingPeriodCode=Code(input.BillingPeriodCode);item.StandardMonthlyAmount=input.StandardMonthlyAmount;item.StandardVisitAmount=input.StandardVisitAmount;item.EffectiveFrom=input.EffectiveFrom;item.EffectiveTo=input.EffectiveTo;item.IsActive=input.IsActive;item.UpdatedAt=DateTime.UtcNow;item.UpdatedByUserId=actor;await db.SaveChangesAsync(token);return MapProduct(item,category.PublicId,category.Name);
    }

    public async Task<SubscriptionRequestResponse> CreateRequest(CreateSubscriptionRequest input,ClaimsPrincipal principal,CancellationToken token)
    {
        ValidateRecurrence(input.Recurrence);var identity=await Customer(principal,token);var category=await EligibleCategory(input.ServiceCategoryId,token);
        var requestKey=Clean(input.IdempotencyKey);if(requestKey is not null){var prior=await db.SubscriptionEvents.AsNoTracking().Where(x=>x.IdempotencyKey==requestKey&&x.EventTypeCode=="REQUEST_CREATED"&&x.SubscriptionRequestId!=null).Select(x=>x.SubscriptionRequestId).SingleOrDefaultAsync(token);if(prior.HasValue&&await db.SubscriptionRequests.AnyAsync(x=>x.Id==prior&&x.CustomerProfileId==identity.ProfileId,token))return await BuildRequest(prior.Value,true,token);}
        CustomerAddress? savedAddress=null;if(input.CustomerAddressId.HasValue)savedAddress=await db.CustomerAddresses.AsNoTracking().SingleOrDefaultAsync(x=>x.PublicId==input.CustomerAddressId&&x.CustomerProfileId==identity.ProfileId&&x.IsActive,token)??throw NotFound("CUSTOMER_ADDRESS_NOT_FOUND","사용할 수 있는 저장주소를 찾을 수 없습니다.");
        var areaPublicId=savedAddress is null?input.AdministrativeAreaId:await db.AdministrativeAreas.Where(x=>x.Id==savedAddress.AdministrativeAreaId).Select(x=>x.PublicId).SingleAsync(token);var area=await db.AdministrativeAreas.SingleOrDefaultAsync(x=>x.PublicId==areaPublicId&&x.IsActive,token)??throw NotFound("AREA_NOT_FOUND","활성 행정구역을 찾을 수 없습니다.");
        var type=Code(input.RequestTypeCode);if(type is not("STANDARD" or "CUSTOM"))throw Bad("SUBSCRIPTION_REQUEST_TYPE_INVALID","구독 요청유형을 확인해 주세요.");
        CareProduct? product=null;if(type=="STANDARD"){if(!input.CareProductId.HasValue)throw Bad("CARE_PRODUCT_REQUIRED","표준상품을 선택해 주세요.");product=await db.CareProducts.SingleOrDefaultAsync(x=>x.PublicId==input.CareProductId&&x.ServiceCategoryId==category.Id&&x.IsActive,token)??throw NotFound("CARE_PRODUCT_NOT_FOUND","사용 가능한 구독상품을 찾을 수 없습니다.");}
        var address=savedAddress is null?Clean(input.DetailAddress):$"{savedAddress.RoadAddress} {savedAddress.DetailAddress}".Trim();var now=DateTime.UtcNow;var item=new SubscriptionRequest{CustomerProfileId=identity.ProfileId,ServiceCategoryId=category.Id,CareProductId=product?.Id,AdministrativeAreaId=area.Id,RequestTypeCode=type,RequestedScopeText=input.RequestedScopeText.Trim(),PreferredStartDate=input.PreferredStartDate,DetailAddress=address,StatusCode="OPEN",CreatedAt=now,CreatedByUserId=identity.UserId,UpdatedAt=now,UpdatedByUserId=identity.UserId};db.SubscriptionRequests.Add(item);await db.SaveChangesAsync(token);
        var rule=NewRule(item.Id,input.Recurrence,identity.UserId,now);db.SubscriptionRecurrenceRules.Add(rule);AddEvent(item.Id,null,null,"REQUEST_CREATED",new{item.PublicId,type,addressSource=savedAddress is null?"DIRECT":"SAVED_ADDRESS"},identity.UserId,requestKey??$"subscription-request:{item.PublicId:N}:created",now);await db.SaveChangesAsync(token);return await BuildRequest(item.Id,true,token);
    }

    public async Task<SubscriptionApplicationResponse> Apply(Guid requestId,SubmitSubscriptionApplicationRequest input,ClaimsPrincipal principal,CancellationToken token)
    {
        ValidateAmounts(input.ProposedMonthlyAmount,input.ProposedVisitAmount);var identity=await Provider(principal,token);var request=await db.SubscriptionRequests.SingleOrDefaultAsync(x=>x.PublicId==requestId,token)??throw NotFound("SUBSCRIPTION_REQUEST_NOT_FOUND","구독 요청을 찾을 수 없습니다.");if(request.StatusCode!="OPEN")throw Conflict("SUBSCRIPTION_REQUEST_NOT_OPEN","신청 가능한 구독 요청이 아닙니다.");
        var existingByKey=await db.SubscriptionApplications.SingleOrDefaultAsync(x=>x.IdempotencyKey==input.IdempotencyKey,token);if(existingByKey is not null)return await MapApplication(existingByKey,token);
        if(await db.SubscriptionApplications.AnyAsync(x=>x.SubscriptionRequestId==request.Id&&x.ProviderProfileId==identity.ProfileId,token))throw Conflict("SUBSCRIPTION_APPLICATION_DUPLICATED","이미 신청한 구독 요청입니다.");
        var result=await eligibility.EvaluateAsync(identity.ProfileId,request.ServiceCategoryId,request.AdministrativeAreaId,token);if(!result.IsEligible)throw Forbidden(result.ReasonCode??"PROVIDER_NOT_ELIGIBLE",EligibilityMessage(result.ReasonCode));
        var now=DateTime.UtcNow;var item=new SubscriptionApplication{SubscriptionRequestId=request.Id,ProviderProfileId=identity.ProfileId,ProposedScopeText=input.ProposedScopeText.Trim(),ProposedMonthlyAmount=input.ProposedMonthlyAmount,ProposedVisitAmount=input.ProposedVisitAmount,AvailableScheduleText=Clean(input.AvailableScheduleText),StatusCode="SUBMITTED",SubmittedAt=now,IdempotencyKey=input.IdempotencyKey.Trim(),CreatedAt=now,CreatedByUserId=identity.UserId,UpdatedAt=now,UpdatedByUserId=identity.UserId};db.SubscriptionApplications.Add(item);await db.SaveChangesAsync(token);AddEvent(request.Id,null,null,"APPLICATION_SUBMITTED",new{item.PublicId,providerId=identity.PublicId},identity.UserId,$"subscription-application:{item.PublicId:N}:submitted",now);await db.SaveChangesAsync(token);return await MapApplication(item,token);
    }

    public async Task<IReadOnlyList<SubscriptionApplicationResponse>> GetApplications(Guid requestId,ClaimsPrincipal principal,CancellationToken token)
    {
        var customer=await Customer(principal,token);var request=await db.SubscriptionRequests.AsNoTracking().SingleOrDefaultAsync(x=>x.PublicId==requestId&&x.CustomerProfileId==customer.ProfileId,token)??throw NotFound("SUBSCRIPTION_REQUEST_NOT_FOUND","구독 요청을 찾을 수 없습니다.");var rows=await db.SubscriptionApplications.AsNoTracking().Where(x=>x.SubscriptionRequestId==request.Id).OrderBy(x=>x.SubmittedAt).ToListAsync(token);var list=new List<SubscriptionApplicationResponse>();foreach(var row in rows)list.Add(await MapApplication(row,token));return list;
    }

    public async Task<SubscriptionContractResponse> SelectProvider(Guid requestId,SelectSubscriptionProviderRequest input,ClaimsPrincipal principal,CancellationToken token)
    {
        var customer=await Customer(principal,token);await using var tx=db.Database.IsRelational()?await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,token):null;
        var request=await db.SubscriptionRequests.SingleOrDefaultAsync(x=>x.PublicId==requestId&&x.CustomerProfileId==customer.ProfileId,token)??throw NotFound("SUBSCRIPTION_REQUEST_NOT_FOUND","구독 요청을 찾을 수 없습니다.");
        var prior=await db.SubscriptionEvents.AsNoTracking().SingleOrDefaultAsync(x=>x.IdempotencyKey==input.IdempotencyKey,token);if(prior?.SubscriptionContractId is long priorContract)return await BuildContract(priorContract,token);
        if(request.SelectedApplicationId.HasValue||request.StatusCode!="OPEN")throw Conflict("SUBSCRIPTION_PROVIDER_ALREADY_SELECTED","이미 공급자가 선택된 요청입니다.");
        var application=await db.SubscriptionApplications.SingleOrDefaultAsync(x=>x.PublicId==input.ApplicationId&&x.SubscriptionRequestId==request.Id&&x.StatusCode=="SUBMITTED",token)??throw NotFound("SUBSCRIPTION_APPLICATION_NOT_FOUND","선택할 공급자 신청을 찾을 수 없습니다.");
        var eligible=await eligibility.EvaluateAsync(application.ProviderProfileId,request.ServiceCategoryId,request.AdministrativeAreaId,token);if(!eligible.IsEligible)throw Conflict(eligible.ReasonCode??"PROVIDER_NOT_ELIGIBLE",EligibilityMessage(eligible.ReasonCode));
        var rule=await db.SubscriptionRecurrenceRules.SingleAsync(x=>x.SubscriptionRequestId==request.Id,token);var provider=await db.ProviderProfiles.SingleAsync(x=>x.Id==application.ProviderProfileId,token);var product=request.CareProductId.HasValue?await db.CareProducts.SingleAsync(x=>x.Id==request.CareProductId,token):null;var now=DateTime.UtcNow;
        var operationPolicy=await db.CategoryOperationPolicies.AsNoTracking().Where(x=>x.CategoryId==request.ServiceCategoryId&&x.IsActive).OrderByDescending(x=>x.EffectiveFrom).FirstOrDefaultAsync(token);
        var completionPolicy=JsonSerializer.Serialize(new{source="CATEGORY_OPERATION_POLICY",policyId=operationPolicy?.PublicId,policyVersion=operationPolicy?.PolicyVersion,requiredPhotoCount=operationPolicy?.RequiredCompletionPhotoCount??0,requiresChecklist=false,requiresVisitVerification=false,evidenceRule=operationPolicy?.CompletionEvidenceRuleText});
        var contract=new SubscriptionContract{SubscriptionRequestId=request.Id,CustomerProfileId=request.CustomerProfileId,ProviderProfileId=provider.Id,ServiceCategoryId=request.ServiceCategoryId,CareProductId=request.CareProductId,SubscriptionApplicationId=application.Id,StatusCode="ACTIVE",StartedAt=now,PriceSnapshotJson=JsonSerializer.Serialize(new{monthlyAmount=application.ProposedMonthlyAmount??product?.StandardMonthlyAmount,visitAmount=application.ProposedVisitAmount??product?.StandardVisitAmount,currency="KRW",source=product is null?"PROVIDER_PROPOSAL":"STANDARD_PRODUCT_AND_PROPOSAL"}),FeePolicySnapshotJson=null,ServiceScopeSnapshotJson=JsonSerializer.Serialize(new{requested=request.RequestedScopeText,proposed=application.ProposedScopeText,product=product?.ServiceScopeText}),RecurrenceSnapshotJson=RecurrenceJson(rule),CompletionPolicySnapshotJson=completionPolicy,ProviderTrustScoreSnapshot=await db.ProviderTrustScoreCurrent.Where(x=>x.ProviderProfileId==provider.Id).Select(x=>x.Score).SingleOrDefaultAsync(token)??provider.TrustScore,CurrencyCode="KRW",CreatedAt=now,CreatedByUserId=customer.UserId,UpdatedAt=now,UpdatedByUserId=customer.UserId};
        db.SubscriptionContracts.Add(contract);application.StatusCode="SELECTED";application.UpdatedAt=now;application.UpdatedByUserId=customer.UserId;var others=await db.SubscriptionApplications.Where(x=>x.SubscriptionRequestId==request.Id&&x.Id!=application.Id&&x.StatusCode=="SUBMITTED").ToListAsync(token);foreach(var other in others){other.StatusCode="NOT_SELECTED";other.UpdatedAt=now;other.UpdatedByUserId=customer.UserId;}request.SelectedApplicationId=application.Id;request.StatusCode="CONTRACTED";request.UpdatedAt=now;request.UpdatedByUserId=customer.UserId;await db.SaveChangesAsync(token);
        AddEvent(request.Id,contract.Id,null,"PROVIDER_SELECTED",new{applicationId=application.PublicId,providerId=provider.PublicId},customer.UserId,input.IdempotencyKey.Trim(),now);AddEvent(request.Id,contract.Id,null,"CONTRACT_CREATED",new{contract.PublicId,feePolicy="POLICY_UNCONFIRMED"},customer.UserId,$"subscription-contract:{contract.PublicId:N}:created",now);AddEvent(request.Id,contract.Id,null,"CONTRACT_ACTIVATED",null,customer.UserId,$"subscription-contract:{contract.PublicId:N}:activated",now);await GenerateVisits(contract,rule,customer.UserId,now,token);await db.SaveChangesAsync(token);if(tx is not null)await tx.CommitAsync(token);return await BuildContract(contract.Id,token);
    }

    public async Task<SubscriptionContractResponse> ChangeState(Guid id,string action,ChangeContractStateRequest input,Guid actorPublicId,CancellationToken token)
    {
        var actor=await AdminId(actorPublicId,token);var item=await Contract(id,token);var now=DateTime.UtcNow;var code=Code(action);
        if(await db.SubscriptionEvents.AnyAsync(x=>x.IdempotencyKey==input.IdempotencyKey,token))return await BuildContract(item.Id,token);
        switch(code){case "PAUSE":if(item.StatusCode!="ACTIVE")throw Conflict("CONTRACT_STATE_INVALID","활성 계약만 일시정지할 수 있습니다.");item.StatusCode="PAUSED";item.PauseStartedAt=now;item.ResumePlannedAt=input.ResumePlannedAt;foreach(var visit in await FutureVisits(item.Id,now,token))visit.StatusCode="PAUSED";break;case "RESUME":if(item.StatusCode!="PAUSED")throw Conflict("CONTRACT_STATE_INVALID","일시정지 계약만 재개할 수 있습니다.");item.StatusCode="ACTIVE";item.PauseStartedAt=null;item.ResumePlannedAt=null;var rule=await db.SubscriptionRecurrenceRules.SingleAsync(x=>x.SubscriptionRequestId==item.SubscriptionRequestId,token);await GenerateVisits(item,rule,actor,now,token,true);break;case "TERMINATE":if(item.StatusCode=="TERMINATED")throw Conflict("CONTRACT_STATE_INVALID","이미 해지된 계약입니다.");item.StatusCode="TERMINATED";item.TerminationRequestedAt??=now;item.TerminatedAt=now;item.EndedAt=now;item.TerminationReason=Clean(input.Reason);foreach(var visit in await FutureVisits(item.Id,now,token))visit.StatusCode="CANCELLED";break;default:throw Bad("CONTRACT_ACTION_INVALID","계약 처리유형을 확인해 주세요.");}
        item.UpdatedAt=now;item.UpdatedByUserId=actor;AddEvent(item.SubscriptionRequestId,item.Id,null,code switch{"PAUSE"=>"PAUSED","RESUME"=>"RESUMED",_=>"TERMINATED"},new{input.Reason,input.ResumePlannedAt},actor,input.IdempotencyKey.Trim(),now);await db.SaveChangesAsync(token);return await BuildContract(item.Id,token);
    }

    public async Task<ProviderSubscriptionContractDetail> GetProviderContract(Guid id,ClaimsPrincipal principal,CancellationToken token)
    {
        var identity=await Provider(principal,token);var row=await(from contract in db.SubscriptionContracts.AsNoTracking()join request in db.SubscriptionRequests.AsNoTracking()on contract.SubscriptionRequestId equals request.Id join customer in db.CustomerProfiles.AsNoTracking()on contract.CustomerProfileId equals customer.Id join user in db.Users.AsNoTracking()on customer.UserId equals user.Id join area in db.AdministrativeAreas.AsNoTracking()on request.AdministrativeAreaId equals area.Id join service in db.ServiceCategories.AsNoTracking()on contract.ServiceCategoryId equals service.Id where contract.PublicId==id&&contract.ProviderProfileId==identity.ProfileId select new{contract,request,customer,user,area,service}).SingleOrDefaultAsync(token)??throw NotFound("SUBSCRIPTION_CONTRACT_NOT_FOUND","구독 계약을 찾을 수 없습니다.");
        var activeAssignment=row.contract.StatusCode=="ACTIVE"&&await db.SubscriptionVisitSchedules.AsNoTracking().AnyAsync(v=>v.SubscriptionContractId==row.contract.Id&&v.ProviderProfileId==identity.ProfileId&&v.StatusCode!="SKIPPED"&&v.StatusCode!="CANCELLED"&&v.StatusCode!="COMPLETED"&&v.StatusCode!="DISPUTED",token);
        var phone=privacyContract.Decide(PrivacyAudience.AssignedProvider,PrivacyField.Phone,activeAssignment);var address=privacyContract.Decide(PrivacyAudience.AssignedProvider,PrivacyField.DetailAddress,activeAssignment);
        if(!phone.CanAccess||!address.CanAccess)throw NotFound("SUBSCRIPTION_CONTRACT_CONTACT_NOT_AVAILABLE","현재 배정된 유효 회차의 업무 연락처만 조회할 수 있습니다.");
        var next=await db.SubscriptionVisitSchedules.Where(v=>v.SubscriptionContractId==row.contract.Id&&v.ProviderProfileId==identity.ProfileId&&v.ScheduledStartAt>=DateTime.UtcNow&&v.StatusCode!="CANCELLED"&&v.StatusCode!="SKIPPED").OrderBy(v=>v.ScheduledStartAt).Select(v=>(DateTime?)v.ScheduledStartAt).FirstOrDefaultAsync(token);
        return new(row.contract.PublicId,Number("SC",row.contract.PublicId),row.customer.DisplayName,row.user.Phone,row.request.DetailAddress,row.area.AreaName,row.service.Name,row.contract.ServiceScopeSnapshotJson,row.contract.RecurrenceSnapshotJson,row.contract.StatusCode,next);
    }

    public async Task<SubscriptionContractResponse> ReplaceProvider(Guid id,ReplaceSubscriptionProviderRequest input,Guid actorPublicId,CancellationToken token)
    {
        var actor=await AdminId(actorPublicId,token);var contract=await Contract(id,token);if(contract.StatusCode is not("ACTIVE" or "PAUSED"))throw Conflict("CONTRACT_STATE_INVALID","운영 중인 계약만 공급자를 교체할 수 있습니다.");if(await db.SubscriptionEvents.AnyAsync(x=>x.IdempotencyKey==input.IdempotencyKey,token))return await BuildContract(contract.Id,token);
        var provider=await db.ProviderProfiles.SingleOrDefaultAsync(x=>x.PublicId==input.ProviderId,token)??throw NotFound("PROVIDER_NOT_FOUND","공급자를 찾을 수 없습니다.");var request=await db.SubscriptionRequests.SingleAsync(x=>x.Id==contract.SubscriptionRequestId,token);var valid=await eligibility.EvaluateAsync(provider.Id,contract.ServiceCategoryId,request.AdministrativeAreaId,token);if(!valid.IsEligible)throw Conflict(valid.ReasonCode??"PROVIDER_NOT_ELIGIBLE",EligibilityMessage(valid.ReasonCode));
        var now=DateTime.UtcNow;var old=contract.ProviderProfileId;contract.ProviderProfileId=provider.Id;contract.UpdatedAt=now;contract.UpdatedByUserId=actor;foreach(var visit in await FutureVisits(contract.Id,now,token))visit.ProviderProfileId=provider.Id;AddEvent(contract.SubscriptionRequestId,contract.Id,null,"PROVIDER_REPLACED",new{oldProviderId=old,newProviderId=provider.Id,input.Reason},actor,input.IdempotencyKey.Trim(),now);await db.SaveChangesAsync(token);return await BuildContract(contract.Id,token);
    }

    public async Task<SubscriptionScheduleChangeResponse> RequestScheduleChange(Guid visitId,RequestScheduleChangeRequest input,ClaimsPrincipal principal,CancellationToken token)
    {
        var requestingUser=await UserId(principal,token);var targetVisit=await Visit(visitId,token);var authorized=await db.SubscriptionContracts.AnyAsync(contract=>contract.Id==targetVisit.SubscriptionContractId&&(db.CustomerProfiles.Any(customer=>customer.Id==contract.CustomerProfileId&&customer.UserId==requestingUser)||db.ProviderProfiles.Any(provider=>provider.Id==contract.ProviderProfileId&&provider.UserId==requestingUser)),token);if(!authorized)throw NotFound("SUBSCRIPTION_VISIT_NOT_FOUND","구독 회차를 찾을 수 없습니다.");
        var user=await UserId(principal,token);var visit=await Visit(visitId,token);if(visit.ScheduledStartAt<=DateTime.UtcNow)throw Conflict("PAST_VISIT_IMMUTABLE","과거 회차 일정은 변경할 수 없습니다.");var existing=await db.SubscriptionScheduleChanges.SingleOrDefaultAsync(x=>x.IdempotencyKey==input.IdempotencyKey,token);if(existing is not null)return MapChange(existing);
        var now=DateTime.UtcNow;var item=new SubscriptionScheduleChange{SubscriptionVisitScheduleId=visit.Id,RequestedByUserId=user,OldScheduleJson=JsonSerializer.Serialize(new{start=visit.ScheduledStartAt,end=visit.ScheduledEndAt}),NewScheduleJson=JsonSerializer.Serialize(new{start=input.ScheduledStartAt,end=input.ScheduledEndAt}),Reason=input.Reason.Trim(),StatusCode="REQUESTED",RequestedAt=now,IdempotencyKey=input.IdempotencyKey.Trim(),CreatedAt=now,UpdatedAt=now};db.SubscriptionScheduleChanges.Add(item);var contract=await db.SubscriptionContracts.SingleAsync(x=>x.Id==visit.SubscriptionContractId,token);AddEvent(contract.SubscriptionRequestId,contract.Id,visit.Id,"SCHEDULE_CHANGE_REQUESTED",new{item.PublicId,input.ScheduledStartAt,input.ScheduledEndAt},user,input.IdempotencyKey.Trim(),now);Audit(user,"SCHEDULE_CHANGE_REQUESTED","SUBSCRIPTION_SCHEDULE_CHANGE",item.PublicId,null,new{item.StatusCode},input.Reason,principal.IsInRole(RoleCodes.Customer)?RoleCodes.Customer:RoleCodes.Provider);await db.SaveChangesAsync(token);return MapChange(item);
    }

    public async Task<SubscriptionScheduleChangeResponse> DecideScheduleChange(Guid changeId,DecideScheduleChangeRequest input,ClaimsPrincipal principal,CancellationToken token)
    {
        var actor=await IdentityUser(principal,token);var item=await db.SubscriptionScheduleChanges.SingleOrDefaultAsync(x=>x.PublicId==changeId,token)??throw NotFound("SCHEDULE_CHANGE_NOT_FOUND","일정 변경 요청을 찾을 수 없습니다.");var visit=await db.SubscriptionVisitSchedules.SingleAsync(x=>x.Id==item.SubscriptionVisitScheduleId,token);var contract=await db.SubscriptionContracts.SingleAsync(x=>x.Id==visit.SubscriptionContractId,token);var customerUser=await db.CustomerProfiles.Where(x=>x.Id==contract.CustomerProfileId).Select(x=>x.UserId).SingleAsync(token);var providerUser=await db.ProviderProfiles.Where(x=>x.Id==contract.ProviderProfileId).Select(x=>x.UserId).SingleAsync(token);var expected=item.RequestedByUserId==customerUser?providerUser:item.RequestedByUserId==providerUser?customerUser:0;if(actor.Id!=expected)throw NotFound("SCHEDULE_CHANGE_NOT_FOUND","상대방에게 요청된 일정 변경만 결정할 수 있습니다.");return await DecideScheduleChangeCore(item,visit,contract,input.Approve,input.IdempotencyKey,input.RowVersion,actor.Id,false,null,actor.Id==customerUser?RoleCodes.Customer:RoleCodes.Provider,token);
    }

    public async Task<SubscriptionScheduleChangeResponse> ForceScheduleChange(Guid changeId,ForceScheduleChangeDecisionRequest input,Guid actorPublicId,CancellationToken token)
    {
